const fs = require('fs');

function isLeap(year) {
    return (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0) ? 29 : 28;
}

function no_of_days_remaining(mon, year) {
    let days = 0;
    const monthDays = [31, isLeap(year), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    for (let i = mon - 1; i < 12; i++) {
        days += monthDays[i];
    }
    return days;
}

function no_of_days_passed(mon, year) {
    let days = 0;
    const monthDays = [31, isLeap(year), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    for (let i = 0; i < mon; i++) {
        days += monthDays[i];
    }
    return days;
}

function no_of_days(year) {
    return 31 * 7 + 30 * 4 + isLeap(year);
}

const input = fs.readFileSync(0, 'utf-8').trim().split('\n');
const [yy1, mm1, dd1] = input[0].trim().split(':').map(Number);
const [yy2, mm2, dd2] = input[1].trim().split(':').map(Number);

let m1, d1, y1, m2, d2, y2;

if (yy2 > yy1) {
    m1 = mm1; y1 = yy1; d1 = dd1;
    m2 = mm2; y2 = yy2; d2 = dd2;
} else {
    m1 = mm2; y1 = yy2; d1 = dd2;
    m2 = mm1; y2 = yy1; d2 = dd1;
}

let nodA = no_of_days_remaining(m1, y1);
let nodC = no_of_days_passed(m2 - 1, y2);
let nodB = 0;

for (let i = y1 + 1; i <= y2 - 1; i++) {
    nodB += no_of_days(i);
}

let nod = (nodA - d1 + 1) + (nodC + d2) + nodB - 1;

if (yy1 === yy2) {
    if (mm2 > mm1) {
        nod = (no_of_days_remaining(mm1, yy1) - dd1 + 1) - (no_of_days_remaining(mm2, yy2) - dd2 + 1);
    } else if (mm2 < mm1) {
        nod = (no_of_days_remaining(mm2, yy2) - dd2 + 1) - (no_of_days_remaining(mm1, yy1) - dd1 + 1);
    } else {
        nod = dd1 > dd2 ? dd1 - dd2 : dd2 - dd1;
    }
}

console.log(nod);

