const fs = require('fs');

function isLeap(year) {
    return (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0) ? 29 : 28;
}

function getMonthLengths(year) {
    return [31, isLeap(year), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
}

function no_of_days_remaining(mon, year) {
    const lengths = getMonthLengths(year);
    let days = 0;
    for (let i = mon - 1; i < 12; i++) {
        days += lengths[i];
    }
    return days;
}

function no_of_days_passed(mon, year) {
    if (mon <= 0) return 0;
    const lengths = getMonthLengths(year);
    let days = 0;
    for (let i = 0; i < mon; i++) {
        days += lengths[i];
    }
    return days;
}

function no_of_days(year) {
